const TAX_RATE = 0.08;
function calculateTax(amount: number) {
  return amount * TAX_RATE;
}
const total = 100 + calculateTax(100);

function formatPrice(amount: number) {
  const total = amount * 1.2;
  return total.toFixed(2);
}
const a = formatPrice(10);
const b = formatPrice(20);

// Version A: direct calculation at call site
function priceAfterDiscount(price: number, discount: number) {
  return price * (1 - discount);
}
const finalA = priceAfterDiscount(100, 0.2);

// Version B: trivial wrapper that delegates
function computePrice(price: number, discount: number) {
  return priceAfterDiscount(price, discount);
}
const finalB = computePrice(100, 0.2);
